-- ##########################################################################################
-- RELEASE SECTION 02/5: APPLY-0207.sql
-- In plain words: Free-trial terms "I agree": the trial owner's agreement (or a teammate's notice) is recorded once per terms version (new table trial_terms_acceptances, kept as a consent record).
-- ##########################################################################################
-- APPLY-0207.sql - paste into the Supabase SQL editor (staging first, then production).
-- Free-trial terms "I agree": the welcome right after a free-trial sign-up now starts with "Your 8-day free
-- trial" (what is included, what you can do, what is locked, what happens after) and the trial owner must tick
-- "I have read and agree to the free-trial terms, the Terms of Service and the Privacy Policy" before entering.
-- This file records that agreement on the server, so it works across devices and is asked only once per terms
-- version. A trial that finished the welcome before this file gets the same terms once as a window; invited
-- teammates get a short notice (no agreement). Paid studios and ended trials are never asked.
-- What it adds: table trial_terms_acceptances (RLS on, no app grants; kept by the trial-data deletion as a
-- consent record), _trial_terms_version(), my_trial_terms_status(), accept_trial_terms(version, user_agent).
-- No existing row is changed or deleted. No DROP / DELETE / UPDATE / TRUNCATE. Safe to run twice.
-- After it: deploy the app (trial-facts.js, trial-demo.js, trial-lock.js, store-api.js, dashboard / login pages).
begin;
-- 0207_trial_terms_acceptance.sql - CANONICAL forward-only.
-- REQUIRES 0045 (tg_studio_read_only), 0116 (_trial_locked), 0166 (_is_trial_org, organizations.is_sample_master),
--          0180 (organizations.trial_welcome_pending), 0184 (_tr184_keep_tables).
--
-- In plain words (owner request 2026-10-18: show the free-trial terms in the onboarding and require "I agree"):
--   * New small table public.trial_terms_acceptances: one row per (studio, person, terms version) with the
--     time and a short browser name (user agent, max 160 printable characters). kind = 'agree' for the
--     trial owner (the person who started the trial) who ticked "I have read and agree ...", 'notice' for an
--     invited teammate who read the short trial notice ("Got it"; no agreement is asked of them).
--     RLS on, no app grants: only the two functions below read or write it. It is a consent record, so the
--     60-day trial-data deletion (0184) KEEPS it (added to _tr184_keep_tables, like studio_consent_log).
--   * _trial_terms_version() = 'trial-2026-10-18' (= HelmTrialFacts.VERSION in public/trial-facts.js).
--     A new wording gets a new version: the owner is asked once more, nothing else changes.
--   * my_trial_terms_status(): for the signed-in member of a studio ON its free trial (running, not
--     read-only, not the sample master): must_agree (the owner has not agreed to this version yet ->
--     the welcome keeps showing "Your 8-day free trial" as its first step, on every device; an owner
--     who finished the welcome before this file gets a one-time "agree" window instead), notice (an
--     invited teammate has not seen the short notice yet). Paid studios, ended trials and clients:
--     everything false - nothing is ever asked of them.
--   * accept_trial_terms(version, user_agent): records it for the caller (insert once; a second call
--     changes nothing). Refuses a different version (a stale cached page), anybody signed out, a client
--     login, and a studio that is not on its free trial. An ended / read-only trial is answered
--     'not_needed' and nothing is written. The owner's agreement also writes one audit_log row.
--   No existing row is changed or deleted. Additive + idempotent: create table / index if not exists,
--   create or replace, one in-place list patch done once. No DROP, DELETE, UPDATE or TRUNCATE. Safe to run twice.
-- ============================================================================

do $$ begin
  if to_regprocedure('public._is_trial_org(uuid)') is null then
    raise exception '0207: _is_trial_org (0166) is missing'; end if;
  if to_regprocedure('public._trial_locked(uuid)') is null then
    raise exception '0207: _trial_locked (0116) is missing'; end if;
  if to_regprocedure('public.tg_studio_read_only()') is null then
    raise exception '0207: tg_studio_read_only (0045) is missing'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public'
                 and table_name = 'organizations' and column_name = 'trial_welcome_pending') then
    raise exception '0207: organizations.trial_welcome_pending (0180) is missing'; end if;
end $$;

-- ---- 1) the record -----------------------------------------------------------------------------------------
create table if not exists public.trial_terms_acceptances (
  org_id      uuid        not null references public.organizations(id) on delete restrict,
  user_id     uuid        not null,
  version     text        not null check (version ~ '^trial-[0-9]{4}-[0-9]{2}-[0-9]{2}$'),
  kind        text        not null default 'agree' check (kind in ('agree', 'notice')),
  accepted_at timestamptz not null default now(),
  user_agent  text        check (user_agent is null or char_length(user_agent) <= 160),
  primary key (org_id, user_id, version)
);
comment on table public.trial_terms_acceptances is
  '0207: free-trial terms record - owner "I agree" (kind agree) / teammate notice seen (kind notice), per terms version. Definer functions only; kept by the trial-data deletion (consent record).';
create index if not exists trial_terms_acceptances_user_idx on public.trial_terms_acceptances(user_id);
alter table public.trial_terms_acceptances enable row level security;
revoke all on table public.trial_terms_acceptances from public;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then execute 'revoke all on table public.trial_terms_acceptances from anon'; end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then execute 'revoke all on table public.trial_terms_acceptances from authenticated'; end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then execute 'grant select on table public.trial_terms_acceptances to service_role'; end if;
  -- the same read-only guard as every studio table (rows are only written while the trial runs anyway)
  if not exists (select 1 from pg_trigger where tgrelid = 'public.trial_terms_acceptances'::regclass and tgname = 'zzz_studio_read_only') then
    execute 'create trigger zzz_studio_read_only before insert or update or delete on public.trial_terms_acceptances '
            'for each row execute function public.tg_studio_read_only(''org_id'')';
  end if;
end $$;
-- (no policies on purpose: only the SECURITY DEFINER functions below read or write this table)

-- ---- 2) the current terms version ------------------------------------------------------------------------------
create or replace function public._trial_terms_version()
returns text language sql immutable set search_path = '' as $$
  -- trial-terms-0207: = HelmTrialFacts.VERSION (public/trial-facts.js)
  select 'trial-2026-10-18'::text;
$$;

-- the caller's view of the studio's free trial: is it running, and is the caller its owner?
-- owner = the person who started the trial (organizations.created_by); when that person is no longer in the
-- studio, its admins stand in (so somebody can always agree).
create or replace function public._tt207_ctx()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- trial-terms-0207
declare v_uid uuid := auth.uid(); v_org uuid; v_role text; o public.organizations; v_trial boolean := false; v_owner boolean := false;
begin
  if v_uid is null then return jsonb_build_object('signed_in', false); end if;
  v_org := public.current_org_id();
  v_role := coalesce(public.user_role(), '');
  if v_org is null or v_role in ('', 'client') then
    return jsonb_build_object('signed_in', true, 'org_id', v_org, 'member', false, 'trial', false, 'owner', false);
  end if;
  select * into o from public.organizations x where x.id = v_org;
  v_trial := o.id is not null and not coalesce(o.is_sample_master, false)
             and coalesce(public._is_trial_org(v_org), false)
             and not coalesce(public._trial_locked(v_org), false);
  v_owner := (o.created_by is not null and o.created_by = v_uid)
             or (coalesce(public.is_admin(), false)
                 and not exists (select 1 from public.profiles p where p.id = o.created_by and p.org_id = v_org));
  return jsonb_build_object('signed_in', true, 'org_id', v_org, 'member', true, 'trial', v_trial, 'owner', v_owner,
                            'welcome_pending', coalesce(o.trial_welcome_pending, false));
end $$;

-- ---- 3) status for the app ---------------------------------------------------------------------------------
create or replace function public.my_trial_terms_status()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- trial-terms-0207: {version, trial, owner, accepted, accepted_at, kind, must_agree, notice, welcome_pending}
declare c jsonb := public._tt207_ctx(); v_ver text := public._trial_terms_version(); a public.trial_terms_acceptances;
  v_trial boolean; v_owner boolean;
begin
  if not coalesce((c ->> 'signed_in')::boolean, false) then raise exception 'not authorized' using errcode = '42501'; end if;
  v_trial := coalesce((c ->> 'trial')::boolean, false);
  v_owner := v_trial and coalesce((c ->> 'owner')::boolean, false);
  if v_trial then
    select * into a from public.trial_terms_acceptances t
     where t.org_id = (c ->> 'org_id')::uuid and t.user_id = auth.uid() and t.version = v_ver;
  end if;
  return jsonb_build_object('version', v_ver, 'trial', v_trial, 'owner', v_owner,
    'accepted', a.org_id is not null, 'accepted_at', a.accepted_at, 'kind', a.kind,
    'must_agree', v_owner and a.org_id is null,
    'notice', v_trial and not v_owner and a.org_id is null,
    'welcome_pending', v_trial and coalesce((c ->> 'welcome_pending')::boolean, false));
end $$;

-- ---- 4) record it ------------------------------------------------------------------------------------------
create or replace function public.accept_trial_terms(p_version text, p_user_agent text default null)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
-- trial-terms-0207: the trial owner agrees / a teammate saw the notice (once per terms version)
declare c jsonb := public._tt207_ctx(); v_ver text := public._trial_terms_version(); v_org uuid; v_kind text;
  v_ua text; v_hdr text; v_n int; a public.trial_terms_acceptances;
begin
  if not coalesce((c ->> 'signed_in')::boolean, false) or not coalesce((c ->> 'member')::boolean, false) then
    raise exception 'not authorized' using errcode = '42501'; end if;
  if p_version is distinct from v_ver then
    raise exception 'These free-trial terms are out of date. Reload the page to read the current terms.'
      using errcode = '22023', hint = 'trial_terms_version'; end if;
  v_org := (c ->> 'org_id')::uuid;
  if not coalesce((c ->> 'trial')::boolean, false) then
    -- an ended (read-only) trial has nothing to agree to; a paid studio / the sample master never uses this
    if coalesce(public._is_trial_org(v_org), false) then
      return jsonb_build_object('result', 'not_needed', 'version', v_ver); end if;
    raise exception 'only a studio on its free trial uses these terms' using errcode = '22023'; end if;
  v_kind := case when coalesce((c ->> 'owner')::boolean, false) then 'agree' else 'notice' end;
  -- the browser name: PostgREST's request header first, else what the page sent; printable ASCII, 160 max
  begin v_hdr := (nullif(current_setting('request.headers', true), '')::jsonb) ->> 'user-agent';
  exception when others then v_hdr := null; end;
  v_ua := nullif(left(btrim(regexp_replace(coalesce(nullif(v_hdr, ''), p_user_agent, ''), '[^ -~]+', '', 'g')), 160), '');
  insert into public.trial_terms_acceptances(org_id, user_id, version, kind, accepted_at, user_agent)
    values (v_org, auth.uid(), v_ver, v_kind, now(), v_ua)
  on conflict (org_id, user_id, version) do nothing;
  get diagnostics v_n = row_count;
  if v_n > 0 and v_kind = 'agree' then
    insert into public.audit_log(actor, actor_email, action, entity, entity_id, changed, org_id, at)
      select auth.uid(), (select u.email from auth.users u where u.id = auth.uid()), 'trial.terms_accepted',
             'organizations', v_org::text, jsonb_build_object('version', v_ver), v_org, now();
  end if;
  select * into a from public.trial_terms_acceptances t where t.org_id = v_org and t.user_id = auth.uid() and t.version = v_ver;
  return jsonb_build_object('result', case when v_n > 0 then 'ok' else 'already' end, 'version', v_ver,
                            'kind', a.kind, 'accepted_at', a.accepted_at);
end $$;

-- ---- 5) privileges -------------------------------------------------------------------------------------------
do $$ declare f text; begin
  foreach f in array array['public._trial_terms_version()', 'public._tt207_ctx()', 'public.my_trial_terms_status()',
                           'public.accept_trial_terms(text, text)'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', f); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', f); end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant execute on function public.my_trial_terms_status() to authenticated';
    execute 'grant execute on function public.accept_trial_terms(text, text) to authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public._trial_terms_version() to service_role';
    execute 'grant execute on function public.my_trial_terms_status() to service_role';
  end if;
end $$;

-- ---- 6) trial retention (0184): the record is consent evidence -> KEPT, never purged ----------------------------
do $$ declare v_def text; begin
  if to_regprocedure('public._tr184_keep_tables()') is null then return; end if;
  v_def := pg_get_functiondef('public._tr184_keep_tables()'::regprocedure);
  if position('''trial_terms_acceptances''' in v_def) > 0 then return; end if;
  if position('''trial_grants'', ''trial_extensions''' in v_def) = 0 then
    raise notice '0207: _tr184_keep_tables has an unexpected body - left unchanged'; return;
  end if;
  execute replace(v_def, '''trial_grants'', ''trial_extensions''',
                  '''trial_grants'', ''trial_extensions'', ''trial_terms_acceptances''');
end $$;

notify pgrst, 'reload schema';
commit;

-- VERIFY (every row should say ok = true)
select item, ok from (values
  ('01 table trial_terms_acceptances exists with RLS on and no permissive policy',
     coalesce((select relrowsecurity from pg_class where oid = to_regclass('public.trial_terms_acceptances')), false)
     and not exists (select 1 from pg_policy where polrelid = to_regclass('public.trial_terms_acceptances') and polpermissive)),
  ('02 the app cannot read or write the table directly',
     not has_table_privilege('anon', 'public.trial_terms_acceptances', 'select')
     and not has_table_privilege('authenticated', 'public.trial_terms_acceptances', 'select')
     and not has_table_privilege('authenticated', 'public.trial_terms_acceptances', 'insert')),
  ('03 studio read-only guard attached',
     exists (select 1 from pg_trigger where tgrelid = to_regclass('public.trial_terms_acceptances') and tgname = 'zzz_studio_read_only')),
  ('04 my_trial_terms_status + accept_trial_terms: SECURITY DEFINER, empty search_path',
     coalesce((select bool_and(prosecdef and 'search_path=""' = any(proconfig)) from pg_proc
               where oid in (to_regprocedure('public.my_trial_terms_status()'), to_regprocedure('public.accept_trial_terms(text,text)'))), false)),
  ('05 signed-in app may call them; anon may not',
     has_function_privilege('authenticated', 'public.my_trial_terms_status()', 'execute')
     and has_function_privilege('authenticated', 'public.accept_trial_terms(text,text)', 'execute')
     and not has_function_privilege('anon', 'public.my_trial_terms_status()', 'execute')
     and not has_function_privilege('anon', 'public.accept_trial_terms(text,text)', 'execute')),
  ('06 terms version is trial-2026-10-18', public._trial_terms_version() = 'trial-2026-10-18'),
  ('07 trial-data deletion keeps the record (listed once, never purged)',
     'trial_terms_acceptances' = any(public._tr184_keep_tables())
     and array_length(array_positions(public._tr184_keep_tables(), 'trial_terms_acceptances'), 1) = 1
     and not ('trial_terms_acceptances' = any(public._tr184_purge_tables()))),
  ('08 every studio table is still classified for the trial-data deletion',
     not exists (select 1 from unnest(public._tr184_org_tables()) t
                  where t <> all(public._tr184_purge_tables()) and t <> all(public._tr184_keep_tables())))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 03/5: APPLY-0208.sql
-- In plain words: Empty draft quotes are cleaned up again: the quotes check quotes_deleted_reason_chk now also allows the clean-up reason 'auto_empty_draft' (superset of today's values; no row written).
-- ##########################################################################################
-- APPLY-0208.sql - paste into the Supabase SQL editor (STAGING first; production when the owner says go).
-- Empty draft quotes can be cleaned up again: the clean-up of EMPTY drafts (0141, Quotes page open + daily) moved
-- nothing, because the quotes check quotes_deleted_reason_chk (0040) did not allow its reason 'auto_empty_draft'.
-- This widens that check to every value it allows today + 'auto_empty_draft' (drop + add NOT VALID + VALIDATE in
-- one transaction). No row is written or deleted here; no other table, column, function or policy changes.
-- Safe to run twice (the 2nd run changes nothing). ASCII only. No edge function to redeploy.
begin;
-- 0208_quote_deleted_reason_auto_draft.sql - CANONICAL forward-only.
-- REQUIRES 0040 (quotes.deleted_reason + check quotes_deleted_reason_chk) and 0141 (empty-draft clean-up).
--
-- In plain words: the daily / on-open clean-up of EMPTY draft quotes (0141) has never moved anything to the
-- Deleted shelf, because it stamps deleted_reason = 'auto_empty_draft' and the 0040 check
-- quotes_deleted_reason_chk only allowed 'manual' and 'link_expired' (the update failed with 23514).
-- This widens that check to the SUPERSET: every value the live check allows today (read from the database,
-- so a value added there by hand is kept too) + 'auto_empty_draft'.
--   * Only runs when the live check does not allow 'auto_empty_draft' yet (the 2nd run changes nothing).
--   * Drop + re-add inside ONE transaction (no moment without the check), added NOT VALID and then
--     VALIDATEd: every existing row met the narrower check, so it meets the wider one.
--   * No row is read for change, written or deleted; no other table, column, function or policy changed.
-- Additive + idempotent. ASCII only.

do $$
declare v_def text; v_vals text[]; v_list text;
begin
  select pg_get_constraintdef(c.oid) into v_def
    from pg_constraint c
   where c.conname = 'quotes_deleted_reason_chk' and c.conrelid = 'public.quotes'::regclass;
  if v_def is not null and v_def like '%''auto_empty_draft''%' then
    return;                                                    -- already widened
  end if;
  -- every quoted value the live check allows today (none when the check is missing)
  select coalesce(array_agg(distinct m[1]), '{}') into v_vals
    from regexp_matches(coalesce(v_def, ''), '''([^'']*)''', 'g') m;
  v_vals := array(select distinct x from unnest(v_vals || array['manual', 'link_expired', 'auto_empty_draft']) x order by x);
  select string_agg(quote_literal(x), ', ' order by x) into v_list from unnest(v_vals) x;
  alter table public.quotes drop constraint if exists quotes_deleted_reason_chk;
  execute format('alter table public.quotes add constraint quotes_deleted_reason_chk'
                 ' check (deleted_reason is null or deleted_reason in (%s)) not valid', v_list);
end $$;
alter table public.quotes validate constraint quotes_deleted_reason_chk;
commit;

-- VERIFY (every row must say ok = true)
select item, ok from (values
  ('01 quotes_deleted_reason_chk allows manual, link_expired and auto_empty_draft (and empty)',
     exists (select 1 from pg_constraint c where c.conname = 'quotes_deleted_reason_chk' and c.conrelid = 'public.quotes'::regclass
              and pg_get_constraintdef(c.oid) like '%''auto_empty_draft''%' and pg_get_constraintdef(c.oid) like '%''manual''%'
              and pg_get_constraintdef(c.oid) like '%''link_expired''%' and pg_get_constraintdef(c.oid) ilike '%deleted_reason IS NULL%')),
  ('02 the check is validated and there is exactly one',
     (select count(*) from pg_constraint c where c.conname = 'quotes_deleted_reason_chk' and c.conrelid = 'public.quotes'::regclass
       and c.convalidated) = 1),
  ('03 the empty-draft clean-up (0141) is installed and still stamps auto_empty_draft',
     to_regprocedure('public._discard_empty_drafts_for(uuid, integer)') is not null
     and position('auto_empty_draft' in pg_get_functiondef('public._discard_empty_drafts_for(uuid, integer)'::regprocedure)) > 0),
  ('04 the other shelf checks are unchanged (archived reason, one shelf)',
     exists (select 1 from pg_constraint where conname = 'quotes_archived_reason_chk' and conrelid = 'public.quotes'::regclass)
     and exists (select 1 from pg_constraint where conname = 'quotes_shelf_one_chk' and conrelid = 'public.quotes'::regclass))
) v(item, ok) order by item;

-- ##########################################################################################
-- RELEASE SECTION 04/5: APPLY-0236.sql
-- In plain words: One meaning of "in the free trial": checkout-started trials get the trial screens + client Test mode; package / message settings and sample clear / reset / switch refused in the trial; the admin's linked staff row is not a staff slot.
-- ##########################################################################################
-- APPLY-0236.sql - paste into the Supabase SQL editor (STAGING first; production when the owner says go).
-- Run AFTER APPLY-0203.sql (APPLY-RELEASE-1018.sql runs everything in the right order in one paste).
-- Free trial, one meaning of "in the trial" (QA of the release build, B1 / B12 / B13):
--   * a trial started from the plan / checkout page (no organizations.trial_ends_at) now gets the trial screens
--     (my_trial_org / my_trial_access) and its client can use Test mode confirm on the approval page;
--   * package flow settings and automatic client message / follow-up settings cannot be changed in the trial;
--     the sample data cannot be cleared, reset or switched off from the app during the trial;
--   * the admin's own login-linked staff row no longer uses one of the 2 trial staff slots.
-- What it touches: 8 functions wrapped (old bodies kept as <name>__pre0236, no app grants), 7 function bodies
-- re-issued (same signatures + grants), 1 helper. No table, column or policy changed; no row written or deleted.
-- organizations.trial_ends_at is NOT back-filled (read-only lock + trial retention stay as they are).
-- Safe to run twice. ASCII only.
begin;
-- 0236_trial_definition_unify.sql - CANONICAL forward-only.
-- REQUIRES 0166 (_is_trial_org), 0173 (_tl173_trial_locked / _tl173_guard / _tl173_tg_create_cap),
--          0128 + 0176 (_trial_test_mode_ok / trial_test_mode_for_token), 0183 (_trial_effective_end,
--          _trial_locked, my_trial_org, my_trial_access), 0181 (_tl181_used / cap triggers / trial_create_log),
--          0069 (pkg_settings_set), 0078 (comms_settings_set), 0097 / 0100 / 0127 / 0166 / 0185 (sample data RPCs),
--          0041 (crew_members.profile_id).
--
-- In plain words (local QA of the release build, bugs B1 / B12 / B13; paid studios never reach a new check):
--   B1  ONE meaning of "in the free trial". The caps and the lockdown (0173 / 0181 / 0203) ask the
--       subscription (studio_subscriptions.status = 'trial', _is_trial_org). The trial banner data
--       (my_trial_org / my_trial_access) and the client-approval test mode (_trial_test_mode_ok, used by
--       trial_test_mode_for_token / trial_test_approve) still asked organizations.trial_ends_at, which a trial
--       started from the plan / checkout page (0056 my_start_trial, 0058) never sets. Such a studio was locked
--       down like a trial but got no trial screens and its client could not approve (only real OTP channels,
--       which the trial blocks). Now:
--         * _trial_test_mode_ok = the studio is on its free trial by the subscription (_tl173_trial_locked:
--           status 'trial', not the sample master), no active plan, not read-only (_trial_locked), and the
--           trial end - organizations.trial_ends_at (+ an HQ extension) or, when that is empty, the end of the
--           day studio_subscriptions.trial_ends_at - is not past (no end recorded at all = allowed).
--         * my_trial_org / my_trial_access: same answers as 0183 for a self-serve trial; a studio whose
--           organizations.trial_ends_at is empty is a trial when its subscription is 'trial' (not the sample
--           master), with ends_at = the end of studio_subscriptions.trial_ends_at.
--       organizations.trial_ends_at is NOT back-filled on purpose: the 0183 read-only lock and the 0184 trial
--       retention (data deletion after the trial, behind the owner switch) are keyed on it, and filling it
--       would make checkout-started trials eligible for both. _trial_effective_end / _trial_locked /
--       _trial_expired_at are unchanged. Self-serve sign-up (0180 / 0190 / 0201) still sets both dates.
--   B12 More settings refused on the server in the trial (same-signature wrappers, originals kept as
--       <name>__pre0236 with no app grants): package flow settings (pkg_settings_set) and automatic client
--       messages / follow-ups / low-stock / WhatsApp forwarding settings (comms_settings_set) - "Not available
--       in the free trial. Upgrade to use this." (42501, hint trial_locked). The sample data cannot be
--       cleared, reset or switched from the app while the studio is on its free trial: clear_demo_data,
--       clear_sample_data, reset_demo_data, set_trial_mode, trial_demo_choice, delete_all_sample_data
--       (after upgrading they work exactly as before; seed_demo_data - fill-only - is unchanged).
--   B13 Staff cap: the trial admin's own login-linked staff row ("Linked account", crew_members.profile_id set
--       by the 0041 member sync) no longer uses one of the 2 staff slots. _tl181_used, the 0181 cap check +
--       log and the 0173 cap trigger skip / do not count crew_members rows linked to a login, so 2 staff
--       members can be added by hand. The app can never set profile_id itself (0041 guard).
--
-- Changes: 8 RPCs wrapped (originals kept as <name>__pre0236), 7 function bodies re-issued (same
-- signatures + grants). No table, column, index, policy or row is created, changed or deleted. Additive +
-- idempotent: safe to run twice. ASCII only.
-- ROLLBACK (manual, only if ever needed; no data involved): for each wrapped f: drop function public.f(args);
-- alter function public.f__pre0236(args) rename to f; grant execute on it to authenticated, service_role;
-- re-run 0128 section 1 (_trial_test_mode_ok), 0183 sections 5 + 6 (my_trial_org / my_trial_access),
-- 0181 (_tl181_used / _tl181_tg_cap_check / _tl181_tg_cap_log) and 0173 section 1 (_tl173_tg_create_cap).

do $$ begin
  if to_regprocedure('public._is_trial_org(uuid)') is null or to_regprocedure('public._tl173_trial_locked(uuid)') is null
     or to_regprocedure('public._tl173_guard()') is null then raise exception 'STOP: 0166 + 0173 (trial lockdown) are not applied'; end if;
  if to_regprocedure('public._trial_effective_end(uuid)') is null or to_regprocedure('public._trial_locked(uuid)') is null
     or to_regprocedure('public.my_trial_org()') is null or to_regprocedure('public.my_trial_access()') is null then
    raise exception 'STOP: 0183 (trial expiry) is not applied'; end if;
  if to_regprocedure('public._trial_test_mode_ok(uuid)') is null then raise exception 'STOP: 0128 (trial test mode) is not applied'; end if;
  if to_regprocedure('public._tl181_used(uuid,text)') is null or to_regclass('public.trial_create_log') is null then
    raise exception 'STOP: 0181 (trial guards) is not applied'; end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'crew_members'
                   and column_name = 'profile_id') then raise exception 'STOP: 0041 (crew_members.profile_id) is not applied'; end if;
end $$;

-- ---- B1) one trial end: organizations.trial_ends_at (+ HQ extension), else the subscription's end day -------
create or replace function public._tu236_trial_end(p_org uuid)
returns timestamptz language sql stable security definer set search_path = '' as $$
  -- trial-unify-0236: the 0183 effective end (self-serve trial + an approved extension); a trial started from
  -- the plan / checkout page has no organizations.trial_ends_at -> the end of its subscription trial day (UTC)
  select coalesce(public._trial_effective_end(p_org),
                  (select (s.trial_ends_at + 1)::timestamp at time zone 'UTC'
                     from public.studio_subscriptions s where s.org_id = p_org and s.trial_ends_at is not null));
$$;

create or replace function public._trial_test_mode_ok(p_org uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  -- helm-0128-trial-test trial-unify-0236: the same "in the free trial" as the caps and the lockdown
  -- (_tl173_trial_locked = subscription status 'trial', not the sample master); no active plan, not read-only,
  -- the trial end (self-serve or checkout-started) not past
  select p_org is not null
     and public._tl173_trial_locked(p_org)
     and not exists (select 1 from public.studio_subscriptions s where s.org_id = p_org and s.status = 'active')
     and not public._trial_locked(p_org)
     and coalesce(public._tu236_trial_end(p_org) > now(), true);
$$;

-- banner data: the 0183 body; a studio without organizations.trial_ends_at is a trial when its subscription is
create or replace function public.my_trial_org()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- trial-orgs-0116 unified-trial-0119 trial-reminders-0120 trial-expiry-0183 trial-unify-0236
declare v_org uuid := public.current_org_id(); o public.organizations; s public.studio_subscriptions;
  v_locked boolean; v_end timestamptz; v_paid boolean;
begin
  if auth.uid() is null or v_org is null or coalesce(public.user_role(), '') in ('', 'client') then
    raise exception 'not authorized' using errcode = '42501'; end if;
  select * into o from public.organizations x where x.id = v_org;
  select * into s from public.studio_subscriptions x where x.org_id = v_org;
  v_paid := exists (select 1 from public.subscription_payments sp where sp.org_id = v_org and sp.voided_at is null);
  if s.org_id is null or v_paid
     or not (s.status = 'trial' or (s.status in ('past_due', 'cancelled') and s.trial_ends_at is not null
                                    and s.current_period_end is null))
     or (o.trial_ends_at is null and not public._tl173_trial_locked(v_org)) then
    return jsonb_build_object('is_trial_org', false, 'read_only', false, 'is_admin', coalesce(public.is_admin(), false));
  end if;
  v_end := public._tu236_trial_end(v_org);
  v_locked := public._trial_locked(v_org);
  return jsonb_build_object('is_trial_org', true, 'name', o.name, 'ends_at', v_end,
    'days_left', case when v_end is null then null else greatest(0, ceil(extract(epoch from (v_end - now())) / 86400.0))::int end,
    'ended', coalesce(v_end <= now(), false), 'locked', v_locked, 'read_only', v_locked, 'trial_mode', o.trial_mode,
    'timezone', coalesce(nullif(btrim(o.timezone), ''), 'Asia/Kolkata'),
    'is_admin', coalesce(public.is_admin(), false));
end $$;

create or replace function public.my_trial_access()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
-- trial-staff-0126 trial-expiry-0183 trial-unify-0236
declare v_org uuid; o public.organizations; s public.studio_subscriptions; v_locked boolean; v_owner boolean;
  v_end timestamptz;
begin
  if auth.uid() is null then raise exception 'not authorized' using errcode = '42501'; end if;
  if not public.mfa_ok() then return jsonb_build_object('is_trial_org', false); end if;
  v_org := public.current_org_id__pre0043();
  if v_org is null then return jsonb_build_object('is_trial_org', false); end if;
  select * into o from public.organizations x where x.id = v_org;
  select * into s from public.studio_subscriptions x where x.org_id = v_org;
  if o.id is null or s.org_id is null
     or exists (select 1 from public.subscription_payments sp where sp.org_id = v_org and sp.voided_at is null)
     or not (s.status = 'trial' or (s.status in ('past_due', 'cancelled') and s.trial_ends_at is not null
                                    and s.current_period_end is null))
     or (o.trial_ends_at is null and not public._tl173_trial_locked(v_org)) then
    return jsonb_build_object('is_trial_org', false);
  end if;
  v_end := public._tu236_trial_end(v_org);
  v_locked := public._trial_locked(v_org);
  v_owner := o.created_by is not null and o.created_by = auth.uid();
  return jsonb_build_object('is_trial_org', true, 'name', o.name, 'ends_at', v_end,
    'ended', coalesce(v_end <= now(), false), 'locked', v_locked, 'read_only', v_locked, 'is_owner', v_owner,
    'blocked', false,
    'timezone', coalesce(nullif(btrim(o.timezone), ''), 'Asia/Kolkata'));
end $$;

-- ---- B13) staff cap: a login-linked staff row (the admin / a member) is not a staff slot --------------------
create or replace function public._tl181_used(p_org uuid, p_table text)
returns integer language plpgsql stable security definer set search_path = '' as $$
-- trial-guards-0181 trial-unify-0236 (crew_members: rows linked to a login are not counted)
declare n integer;
begin
  if p_org is null or p_table is null
     or p_table not in ('leads', 'quotes', 'inventory_items', 'vendors', 'crew_members', 'venues') then return 0; end if;
  if p_table = 'crew_members' then
    select (select count(*) from public.trial_create_log l
             where l.org_id = p_org and l.entity = 'crew_members'
               and not exists (select 1 from public.crew_members c
                                where c.org_id = p_org and c.id::text = l.row_id and c.profile_id is not null))::integer
         + (select count(*) from public.crew_members x
             where x.org_id = p_org and not x.is_demo and x.profile_id is null
               and not exists (select 1 from public.trial_create_log l
                                where l.org_id = p_org and l.entity = 'crew_members' and l.row_id = x.id::text))::integer
      into n;
    return coalesce(n, 0);
  end if;
  execute format('select (select count(*) from public.trial_create_log l where l.org_id = $1 and l.entity = $2)::integer
                       + (select count(*) from public.%I x where x.org_id = $1 and not x.is_demo
                            and not exists (select 1 from public.trial_create_log l
                                             where l.org_id = $1 and l.entity = $2 and l.row_id = x.id::text))::integer', p_table)
    into n using p_org, p_table;
  return coalesce(n, 0);
end $$;

create or replace function public._tl181_tg_cap_check()
returns trigger language plpgsql security definer set search_path = '' as $$
-- trial-guards-0181: 2 own rows created IN TOTAL per list in the free trial
-- trial-unify-0236: a staff row linked to a login (member sync) is not a slot
begin
  if new.org_id is null or coalesce(new.is_demo, false) then return new; end if;
  if tg_table_name = 'crew_members' and (to_jsonb(new) ->> 'profile_id') is not null then return new; end if;
  if public._is_system_change() then return new; end if;
  if not public._tl173_trial_locked(new.org_id) then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:cap:' || tg_table_name || ':' || new.org_id::text, 0));
  -- a restored row (same id) that was already counted comes back without using a new slot
  if exists (select 1 from public.trial_create_log l
              where l.org_id = new.org_id and l.entity = tg_table_name and l.row_id = new.id::text) then
    return new;
  end if;
  if public._tl181_used(new.org_id, tg_table_name) >= 2 then
    raise exception 'Free trial limit reached (2). Upgrade to add more.' using errcode = '42501', hint = 'trial_cap';
  end if;
  return new;
end $$;

create or replace function public._tl181_tg_cap_log()
returns trigger language plpgsql security definer set search_path = '' as $$
-- trial-guards-0181: remember the own row the trial studio just added (AFTER INSERT: only rows really saved)
-- trial-unify-0236: a staff row linked to a login (member sync) is not logged
begin
  if new.org_id is null or coalesce(new.is_demo, false) then return null; end if;
  if tg_table_name = 'crew_members' and (to_jsonb(new) ->> 'profile_id') is not null then return null; end if;
  if public._is_system_change() then return null; end if;
  if not public._tl173_trial_locked(new.org_id) then return null; end if;
  insert into public.trial_create_log(org_id, entity, row_id) values (new.org_id, tg_table_name, new.id::text)
    on conflict do nothing;
  return null;
end $$;

create or replace function public._tl173_tg_create_cap()
returns trigger language plpgsql security definer set search_path = '' as $$
-- trial-lockdown-0173 trial-unify-0236 (crew_members: rows linked to a login are not counted)
declare v_n integer;
begin
  if new.org_id is null or coalesce(new.is_demo, false) then return new; end if;
  if tg_table_name = 'crew_members' and (to_jsonb(new) ->> 'profile_id') is not null then return new; end if;
  if public._is_system_change() then return new; end if;
  if not public._tl173_trial_locked(new.org_id) then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended('helm:cap:' || tg_table_name || ':' || new.org_id::text, 0));
  if tg_table_name = 'crew_members' then
    select count(*) into v_n from public.crew_members x where x.org_id = new.org_id and not x.is_demo and x.profile_id is null;
  else
    execute format('select count(*) from public.%I x where x.org_id = $1 and not x.is_demo', tg_table_name) into v_n using new.org_id;
  end if;
  if v_n >= 2 then
    raise exception 'Free trial limit reached (2). Upgrade to add more.' using errcode = '42501', hint = 'trial_cap';
  end if;
  return new;
end $$;

-- ---- B12) more trial wrappers (same pattern as 0173 / 0181) -------------------------------------------------
do $$
declare
  f text; v_new boolean; v_old regprocedure; v_pre regprocedure; v_name text; v_args text; v_idargs text; v_ret text; v_call text; n int; g record;
begin
  foreach f in array array[
    'public.pkg_settings_set(jsonb)', 'public.comms_settings_set(jsonb)',
    'public.clear_demo_data()', 'public.clear_sample_data()', 'public.reset_demo_data()',
    'public.set_trial_mode(text)', 'public.trial_demo_choice(text)', 'public.delete_all_sample_data()'] loop
    v_old := to_regprocedure(f);
    if v_old is null then continue; end if;
    select p.proname, pg_get_function_arguments(p.oid), oidvectortypes(p.proargtypes), pg_get_function_result(p.oid), p.pronargs
      into v_name, v_args, v_idargs, v_ret, n from pg_proc p where p.oid = v_old;
    v_pre := to_regprocedure(format('public.%I(%s)', v_name || '__pre0236', v_idargs));
    v_new := false;
    if v_pre is null then
      -- first run: keep the original under __pre0236 (its grants move with it), then build the wrapper
      execute format('alter function public.%I(%s) rename to %I', v_name, v_idargs, v_name || '__pre0236');
      v_new := true;
    end if;
    select string_agg('$' || i, ', ' order by i) into v_call from generate_series(1, greatest(n, 1)) i where i <= n;
    execute format($w$create or replace function public.%I(%s) returns %s language plpgsql volatile security definer set search_path = '' as $b$
-- trial-unify-0236: free trial check, then the original
begin
  perform public._tl173_guard();
  return public.%I(%s);
end $b$
$w$, v_name, v_args, v_ret, v_name || '__pre0236', coalesce(v_call, ''));
    -- grants (only when the wrapper is new; a re-run keeps what is there): wrapper = the original's
    -- grants; the kept original = definer only
    continue when not v_new;
    execute format('revoke all on function public.%I(%s) from public', v_name, v_idargs);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function public.%I(%s) from anon', v_name, v_idargs); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function public.%I(%s) from authenticated', v_name, v_idargs); end if;
    for g in select distinct r.rolname from pg_proc p, lateral aclexplode(p.proacl) a join pg_roles r on r.oid = a.grantee
              where p.oid = to_regprocedure(format('public.%I(%s)', v_name || '__pre0236', v_idargs)) and a.privilege_type = 'EXECUTE'
                and r.rolname in ('anon', 'authenticated', 'service_role') loop
      execute format('grant execute on function public.%I(%s) to %I', v_name, v_idargs, g.rolname);
    end loop;
    execute format('revoke all on function public.%I(%s) from public', v_name || '__pre0236', v_idargs);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function public.%I(%s) from anon', v_name || '__pre0236', v_idargs); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function public.%I(%s) from authenticated', v_name || '__pre0236', v_idargs); end if;
  end loop;
end $$;

-- ---- privileges (same as before for the re-issued functions) -------------------------------------------------
do $$ declare f text; begin
  foreach f in array array['public._tu236_trial_end(uuid)', 'public._trial_test_mode_ok(uuid)', 'public.my_trial_org()',
                           'public.my_trial_access()', 'public._tl181_used(uuid,text)', 'public._tl181_tg_cap_check()',
                           'public._tl181_tg_cap_log()', 'public._tl173_tg_create_cap()'] loop
    execute format('revoke all on function %s from public', f);
    if exists (select 1 from pg_roles where rolname = 'anon') then execute format('revoke all on function %s from anon', f); end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then execute format('revoke all on function %s from authenticated', f); end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant execute on function public.my_trial_org() to authenticated';
    execute 'grant execute on function public.my_trial_access() to authenticated';
  end if;
